233:    pub fn read_non_empty_line_with_timeout(
234:        &mut self,
235:        timeout: Duration,
236:        context: &str,
237:    ) -> Result<String> {
238:        loop {
239:            let line = self.read_line_with_timeout(timeout, context)?;
240:            let trimmed = line.trim().to_string();
241:            if !trimmed.is_empty() {
242:                return Ok(trimmed);
243:            }
244:        }
245:    }
